import requests

# 白嫖的免费代理
proxies = {
    'http': 'http://27.70.38.29:6666',
    'https': 'https://27.70.38.29:6666',
}
try:
    response = requests.get('https://www.baidu.com', proxies = proxies)
    print(response.text)
except requests.exceptions.ConnectionError as e:
    print('Error', e.args)

